#include "ksStateGlobalSaveTask.h"
#include <array>
#include <iostream>
#include <stdexcept>
using T=ks::StateGlobalSaveTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(unsigned word=0;word<65536;++word){T task;const unsigned enabled=word&255,store=word&256?0:3;std::array<unsigned,256> page{};std::array<unsigned,5> metadata{};unsigned count=0,reads=0,meta=0,clocks=0;auto read=[&](T::Read r){++reads;switch(r){case T::Read::Enabled:return enabled;case T::Read::Part:return word&255;case T::Read::Single:return word;case T::Read::Multi:return word^0xa55a;default:return unsigned(uint8_t(word+task.byteOffset()*17));}};auto write=[&](T::Write w,unsigned value){if(w==T::Write::Scratch){check(task.byteOffset()==count,"Global page byteorder");page[count++]=value;}else metadata[meta++]=value;};while(!task.awaitingProgram()){unsigned c=task.nextClocks(store),n=reads+count+meta;check(!task.advanceBefore(c-1,read,write,store)&&n==reads+count+meta,"Global early effect");check(task.advanceBefore(c,read,write,store)==c,"Global admission");clocks+=c;}check(count==256&&reads==22+3*bool(enabled)&&meta==5*bool(enabled),"Global readwritecounts");for(unsigned i=0;i<256;++i)check(page[i]==(i<21?uint8_t(word+i*17):0),"Global page bytes");if(enabled)check(metadata==std::array<unsigned,5>{{word&255,word>>8,word&255,1,(word^0xa55a)&255}},"Global metadata mapping");unsigned expected=89+21*(20+store)+235*(12+store)+(enabled?99+5*store:0);check(clocks==expected,"Global exact clocks");check(task.retireProgram()&&task.complete()&&!task.retireProgram(),"Global tail retirement");++cases;}std::cout<<"PASS: "<<cases<<" complete global saves,all16bitprogramwords/allflags/late21bytes/235zeros/metadata/deadlines+clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
